    t === nothing || return t
    return self._tables[type_] = TypeSpecificGlobalTable(self.translator, type_, "global-table-$(length(self._tables))")
end

@parity "dart2wasm/lib/table_based_globals.dart:24 TableBasedGlobals.outputTables" function output_tables(self::TableBasedGlobals)::Nothing
