"""
Gets the wasm table used to reference this table in `module_`.

This can either be the table definition itself or an import of it. Imports the table into
`module_` if it is not imported yet.
"""
@parity "dart2wasm/lib/table_based_globals.dart:56 TypeSpecificGlobalTable.getWasmTable" get_wasm_table(self::TypeSpecificGlobalTable, module_::WasmBuilder.ModuleBuilder)::WasmBuilder.IR.AbstractTable = get(self._imported_wasm_tables, self._defined_wasm_table[], module_)

"""
Returns the index for `object` in the table allocating one if necessary; `init_module` and `init`
together give the slot a constant initializer expression, built in that module.
"""
@parity "dart2wasm/lib/table_based_globals.dart:61 TypeSpecificGlobalTable.indexForObject" function index_for_object(self::TypeSpecificGlobalTable, object::GlobalRef,
        init_module::Union{WasmBuilder.ModuleBuilder,Nothing} = nothing, init::Union{Function,Nothing} = nothing)::Int
    (init_module === nothing) == (init === nothing) ||
        reject!(Internal("dart2wasm/lib/table_based_globals.dart:66 TypeSpecificGlobalTable.indexForObject: a module without an initializer, or one without a module"), "TypeSpecificGlobalTable.indexForObject")
    local existing = get(self._table, object, nothing)
    existing === nothing || return existing[1]

    local expression = nothing
    if init_module !== nothing
        expression = WasmBuilder.InstructionsBuilder(init_module, WasmBuilder.IR.ValueType[],
            WasmBuilder.IR.ValueType[WasmBuilder.IR.RefType(self._table_heap_type; nullable = false)]; constant_expression = true)
        init(expression)
    end

    local index = length(self._table)
    self._table[object] = (index, expression)
    return index
end

@parity "dart2wasm/lib/table_based_globals.dart:81 TypeSpecificGlobalTable.output" function output(self::TypeSpecificGlobalTable)::Nothing
    local imported_tables = self._imported_wasm_tables
    local defined = self._defined_wasm_table[]
    for (_, (index, expression)) in self._table
        expression === nothing && continue
        local module_builder = expression.module_builder
        if is_main_module(self.translator, module_builder)
            WasmBuilder.set_expression_at(WasmBuilder.active_expression_segment_builder_for(defined.module_builder.elements[], defined), index, expression)
        else
            # This will generate the imported table if it doesn't already exist.
            local imported_table = get_wasm_table(self, module_builder)
            imported_table isa WasmBuilder.IR.ImportedTable ||
                reject!(Internal("dart2wasm/lib/table_based_globals.dart:92 TypeSpecificGlobalTable.output: the table of another module is a $(typeof(imported_table)), not an import"), "TypeSpecificGlobalTable.output")
            WasmBuilder.set_expression_at(WasmBuilder.active_expression_segment_builder_for(module_builder.elements[], imported_table), index, expression)
        end
    end

    defined.min_size = length(self._table)
    for table in imports(imported_tables)
        table.min_size = length(self._table)
    end
    return nothing
end
